select 'vw_ocupacao_ta' v, count(*) n, md5(string_agg(x::text, '|' order by x::text)) from (select turma_id,data,ta_inicial,ta_final,tempos_consumidos,origem,fato_id,disciplina_id,instrutor_id,fiscal_id,local,herdado,sessao_id,numero_sessao from public.vw_ocupacao_ta) x
union all select 'vw_ocupacao_do_dsa', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select * from public.vw_ocupacao_do_dsa) x
union all select 'vw_chd_por_fato', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select * from public.vw_chd_por_fato) x
union all select 'vw_carga_horaria_turma', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select turma_id,turma_codigo,curso_id,curso_codigo,nome_curso,ano_letivo,status_turma,chr_curricular,ta_aula,ta_extraclasse,ta_avaliacao,ta_vista_prova,chd_executada,ta_aec,ta_tad,ta_tr,ta_estudo_individual,cht_executada,ta_apoio_individualizado,ta_dias_parados,ta_fora_do_dsa from public.vw_carga_horaria_turma) x
union all select 'vw_disciplinas_execucao', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select disciplina_id,disciplina_codigo,curso_id,cod_disciplina,nome_disciplina,carga_horaria_tempos,turma_id,turma_codigo,ano_letivo,previsao_inicio_efetiva,previsao_termino_efetiva,origem_periodo,data_real_inicio,data_real_termino,ta_aula_executados,ta_avaliacao_executados,ta_executados,ta_saldo,ta_fora_do_dsa,nome_no_dsa from public.vw_disciplinas_execucao) x
union all select 'vw_instrutor_carga_anual', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select instrutor_id,instrutor_codigo,ano,ta_ministrado_ano,ta_fiscalizado_ano,ta_previsto_ano,qtd_disciplinas_habilitadas from public.vw_instrutor_carga_anual) x
union all select 'vw_conformidade_tetos', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select * from public.vw_conformidade_tetos) x
union all select 'chd_da_turma_ate(2026-11-03)', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select * from public.chd_da_turma_ate(date '2026-11-03')) x
union all select 'execucao_por_disciplina_ate(2026-11-03)', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select t.id, e.* from public.turmas t cross join lateral public.execucao_por_disciplina_ate(date '2026-11-03', t.id) e) x
union all select 'atividades (categoria, subtipo, tipo)', count(*), md5(string_agg(x::text, '|' order by x::text)) from (select id, categoria_normativa, subtipo, tipo_atividade_id, status, salvo, editado_em from public.atividades_nao_letivas) x;
